// clean tidies user-typed text: trims it, squashes inner whitespace and lowercases it.
function clean(s) {
  return String(s).trim().replace(/\s+/g, ' ').toLowerCase();
}

module.exports = { clean };
const { clean } = require('./clean');

// makeHandle builds the URL handle for a user: "Ada Lovelace" -> "ada-lovelace".
function makeHandle(name) {
  return clean(name).replace(/ /g, '-');
}

module.exports = { makeHandle };
const { clean } = require('./clean');

// displayName is how a user's name appears on their profile page.
function displayName(user) {
  return clean(user.name);
}

module.exports = { displayName };
const { clean } = require('./clean');

// findUsers returns the users whose name contains the query, ignoring case and extra spaces.
function findUsers(users, query) {
  const q = clean(query);
  return users.filter((u) => clean(u.name).includes(q));
}

module.exports = { findUsers };
const test = require('node:test');
const assert = require('node:assert');
const { displayName } = require('../profile');

test('tidies the display name', () => {
  assert.strictEqual(displayName({ name: '  Ada   Lovelace ' }), 'Ada Lovelace');
});
const test = require('node:test');
const assert = require('node:assert');
const { findUsers } = require('../search');

test('finds a user by part of their name', () => {
  const users = [{ name: 'Ada Lovelace' }, { name: 'Alan Turing' }];
  assert.deepStrictEqual(findUsers(users, 'Ada'), [{ name: 'Ada Lovelace' }]);
});
