cat > clean.js <<'EOF'
// tidy trims user-typed text and squashes inner whitespace, keeping the original letter case.
function tidy(s) {
  return String(s).trim().replace(/\s+/g, ' ');
}

// clean tidies user-typed text and lowercases it, for case-insensitive matching and handles.
function clean(s) {
  return tidy(s).toLowerCase();
}

module.exports = { tidy, clean };
EOF
cat > profile.js <<'EOF'
const { tidy } = require('./clean');

// displayName is how a user's name appears on their profile page. It keeps the user's capitalisation.
function displayName(user) {
  return tidy(user.name);
}

module.exports = { displayName };
EOF
cat >> "test\\profile.test.js" <<'EOF'

test('keeps the capitalisation of the display name', () => {
  assert.strictEqual(displayName({ name: 'ada lovelace' }), 'ada lovelace');
  assert.strictEqual(displayName({ name: 'Ada Lovelace' }), 'Ada Lovelace');
});
EOF
npm test 2>&1 | tail -n 20

